tool_input.command:
cat > internal/hook/zz_drift_probe.go <<'EOF'
package hook

import "github.com/punt-labs/ethos/v4/internal/mission"

// probeCancelRunningWorker is a synthetic FOURTH write site for
// DelegationVerdictAborted, in a NEW file in the hook package.
func probeCancelRunningWorker(recordPath, reason string) error {
	return mission.CloseDelegation(recordPath, mission.DelegationVerdictAborted, reason)
}
EOF
echo made

mv internal/hook/zz_drift_probe.go .tmp/zz_drift_probe.go.bak; printf '
// probeCompositeLit is a synthetic fourth write site using a composite literal.
func probeCompositeLit() Delegation {
	return Delegation{Verdict: DelegationVerdictAborted}
}
' >> internal/mission/store.go; go test ./internal/mission/ -run TestAbortedVerdictWriteSites_MatchKnownThree -count=1 2>&1 | tail -20

git checkout -- internal/mission/store.go; printf '
// probeCallArg is a synthetic fourth write site as a call argument.
func probeCallArg(p, r string) error {
	return CloseDelegation(p, DelegationVerdictAborted, r)
}
' >> internal/mission/store.go; go test ./internal/mission/ -run TestAbortedVerdictWriteSites_MatchKnownThree -count=1 2>&1 | tail -20
